def estados_garantia(apps, schema_editor):
    """'Devuelto a proveedor' pasa a llamarse 'En garantía', se crea 'Dado de baja' y los
    equipos que estaban 'Devuelto a sector' se pasan a un envío de garantía por proveedor."""
    Estado = apps.get_model('almacenes', 'EstadoMaterialONU')
    Material = apps.get_model('almacenes', 'Material')
    Envio = apps.get_model('almacenes', 'EnvioGarantia')
    Detalle = apps.get_model('almacenes', 'EnvioGarantiaDetalle')
    Historial = apps.get_model('almacenes', 'HistorialMaterial')
    Usuario = apps.get_model('usuarios', 'Usuario')

    en_garantia, _ = Estado.objects.update_or_create(
        codigo='DEVUELTO_PROVEEDOR',
        defaults={'nombre': 'En garantía', 'descripcion': 'Enviado al proveedor por garantía', 'activo': True,
                  'permite_asignacion': False, 'permite_traspaso': False},
    )
    Estado.objects.get_or_create(
        codigo='BAJA',
        defaults={'nombre': 'Dado de baja', 'descripcion': 'Defectuoso sin reposición del proveedor',
                  'color': '#6B7280', 'activo': True, 'orden': 10,
                  'permite_asignacion': False, 'permite_traspaso': False},
    )

    viejos = Material.objects.filter(estado_onu__codigo='DEVUELTO_SECTOR_SOLICITANTE').select_related('lote')
    usuario = Usuario.objects.filter(is_superuser=True).order_by('id').first() or Usuario.objects.order_by('id').first()
    if not viejos.exists() or usuario is None:
        return
    anio = timezone.localdate().year
    n = Envio.objects.filter(numero__startswith=f'GAR-{anio}-').count()
    por_proveedor = {}
    for m in viejos:
        por_proveedor.setdefault(m.lote.proveedor_id, []).append(m)
    for proveedor_id, equipos in por_proveedor.items():
        n += 1
        envio = Envio.objects.create(
            numero=f'GAR-{anio}-{n:04d}', proveedor_id=proveedor_id, fecha_envio=timezone.localdate(),
            referencia='Migrado de devoluciones anteriores', created_by=usuario,
        )
        for m in equipos:
            Detalle.objects.create(envio=envio, material=m)
            m.estado_onu = en_garantia
            m.save(update_fields=['estado_onu'])
            Historial.objects.create(
                material=m, estado_anterior='DEVUELTO_SECTOR', estado_nuevo='DEVUELTO_PROVEEDOR',
                almacen_anterior_id=m.almacen_actual_id, almacen_nuevo_id=m.almacen_actual_id,
                motivo=f'Pasa a garantía {envio.numero}', usuario_responsable=usuario,
            )


